/* Getting rocks (msgs 6): from the pile.
 * [MSG_GET 20 00 00] */
static void feather1_GetRocks(void)
{
    if (fv_kirk_up == 0) {
        if (rv_took_rocks == 1) {
            feather1_Say(S_1173, T_FEA1N019);
            return;
        }
        svc_Walk(0, 0x90, 0xB6, 6);
        room.busy = 1;
        return;
    }
    feather1_Say(S_1173, T_FEA1N021);
    return;
}

